-- Batch 8/28: 10 providers (bank-commerzbank ... bank-al-sydbank).
-- Idempotent. Run after sql/003_merge_catalog.sql. One file per agent turn.

update public.navigator_workspace as w
set
  payload = jsonb_set(
    w.payload,
    '{providers}',
